# vendor_text_safety.py\n# [LATER-STEP] Moderate vendor notes or memo fields\n\nfrom __future__ import annotations\nfrom dataclasses import dataclass\n\nfrom document_models import ExtractionResult\n\n# Using AWS Comprehend Toxicity detection as the concrete provider\n# Required environment variables: AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY\nfrom boto3 import client as boto3_client\n\ncomprehend = boto3_client('comprehend', region_name='us-east-1')\n\ndef moderate_vendor_text(result: ExtractionResult) -> ExtractionResult:\n    \"\"\"Runs Comprehend toxicity analysis on any vendor‑provided notes.\n\n    Args:\n        result (ExtractionResult): Payload containing raw vendor notes (if present).\n\n    Returns:\n        ExtractionResult: Updated payload with moderation flag and, if needed, a redacted note.\n    \"\"\"\n    notes = result.raw.get('vendor_notes', '')\n    if not notes:\n        return result\n    # Call Comprehend DetectSentiment (can be swapped for DetectModeration)\n    response = comprehend.detect_sentiment(Text=notes, LanguageCode='en')\n    sentiment = response.get('Sentiment')\n    confidence = response.get('SentimentScore', {}).get('POSITIVE', 0.0)\n    # Simple rule: if not positive, flag as unsafe and strip content\n    if sentiment != 'POSITIVE' or confidence < 0.7:\n        result.raw['vendor_notes_moderated'] = False\n        result.raw['vendor_notes'] = '[REDACTED – unsafe content]'\n    else:\n        result.raw['vendor_notes_moderated'] = True\n    return result\n\n# Example usage (uncomment to test):\n# raw = {'vendor_notes': \"Buy widgets from shady supplier.\"}\n# print(moderate_vendor_text(ExtractionResult(raw=raw)))\n
